<div class="page-heading admin-heading"><div><span class="eyebrow">Compliance</span><h1>Audit trail</h1><p>Append-only activity view for security, processing and administrative decisions.</p></div><div class="heading-actions"><button class="button button-outline">↓ Export audit records</button></div></div><div class="report-notice"><span>⌾</span><p>Audit access is restricted. Records include actor, action, affected entity, network address and timestamp. Sensitive values should never be written in plain text.</p></div><section class="card application-table-card"><div class="table-filters"><div class="search-field"><span>⌕</span><input placeholder="Search action, actor or entity"></div><select><option>All modules</option><option>Authentication</option><option>Applications</option><option>Payments</option><option>CMS</option><option>Settings</option></select></div><div class="table-wrap"><table><thead><tr><th>Time</th><th>Actor</th><th>Action</th><th>Entity</th><th>IP address</th><th>Change</th></tr></thead><tbody><?php foreach($logs as $log):?><tr><td><?= format_date($log['created_at'],true) ?></td><td><b><?= e($log['user_name']?:'System / guest') ?></b></td><td><code class="action-code"><?= e($log['action']) ?></code></td><td><?= e($log['entity_type']) ?> <?= $log['entity_id']?'#'.e($log['entity_id']):'' ?></td><td><code><?= e($log['ip_address']) ?></code></td><td><details><summary>Inspect</summary><pre><?= e($log['new_values']?:$log['old_values']?:'No field values recorded') ?></pre></details></td></tr><?php endforeach?></tbody></table></div></section>
